CREATE VIEW spieler AS SELECT account_id,real_name AS echter_name FROM players;
CREATE VIEW gefecht_teilnehmer AS SELECT battle_id AS gefechts_id,vehicle_id AS fahrzeug_id,player_id AS spieler_id,display_name AS angezeigter_name,real_name AS echter_name,alias,tank AS panzer,tier AS stufe,team,total_damage AS gesamt_schaden,shots AS schuesse,hits AS treffer,penetrations AS durchschlaege,spotting_assist AS assist_aufklaerung,tracking_assist AS assist_kette,stun_assist AS assist_betaeubung FROM battle_participants;
CREATE VIEW schaden_eingehend AS SELECT battle_id AS gefechts_id,own_vehicle AS eigenes_fahrzeug,vehicle_id AS fahrzeug_id,life_index AS leben_index,damage AS schaden,direct_hits AS direkte_treffer,penetrating_hits AS durchschlagstreffer,explosion_hits AS explosionstreffer,ammunition_type AS munitionstyp,blocked_damage AS geblockter_schaden,killed_by AS zerstoert_von FROM incoming_damage;
CREATE VIEW schaden_ausgehend AS SELECT battle_id AS gefechts_id,own_vehicle AS eigenes_fahrzeug,vehicle_id AS fahrzeug_id,life_index AS leben_index,damage AS schaden,direct_hits AS direkte_treffer,penetrating_hits AS durchschlagstreffer,explosion_hits AS explosionstreffer,ammunition_type AS munitionstyp FROM outgoing_damage;
CREATE VIEW replay_json AS SELECT replay_path AS replay_pfad,block_index,payload FROM replay_documents;
CREATE VIEW replay_sql_index AS SELECT replay_path AS replay_pfad,captured_at,version FROM projection_index;
CREATE VIEW gefechte AS SELECT battle_id AS gefechts_id,date AS datum,map AS karte,map_id AS karten_id,own_player_id AS eigener_spieler_id,results_available AS ergebnis_vorhanden FROM battles;
    CREATE VIEW v_spieler_gefechte AS SELECT t.*,g.datum,g.karte,g.karten_id,g.eigener_spieler_id,CASE WHEN t.spieler_id=g.eigener_spieler_id THEN 'selbst' WHEN t.team=(SELECT e.team FROM gefecht_teilnehmer e WHERE e.gefechts_id=t.gefechts_id AND e.spieler_id=g.eigener_spieler_id LIMIT 1) THEN 'Mitspieler' WHEN t.team IS NOT NULL AND EXISTS(SELECT 1 FROM gefecht_teilnehmer e WHERE e.gefechts_id=t.gefechts_id AND e.spieler_id=g.eigener_spieler_id AND e.team IS NOT NULL) THEN 'Gegner' ELSE 'unbekannt' END AS zuordnung FROM gefecht_teilnehmer t JOIN gefechte g USING(gefechts_id);
    CREATE VIEW v_schaden_eingehend AS SELECT s.*,t.spieler_id,t.echter_name,t.angezeigter_name,t.alias,t.panzer,t.stufe,t.team,t.zuordnung,t.datum,t.karte FROM schaden_eingehend s JOIN v_spieler_gefechte t USING(gefechts_id,fahrzeug_id);
    CREATE VIEW v_schaden_ausgehend AS SELECT s.*,t.spieler_id,t.echter_name,t.angezeigter_name,t.alias,t.panzer,t.stufe,t.team,t.zuordnung,t.datum,t.karte FROM schaden_ausgehend s JOIN v_spieler_gefechte t USING(gefechts_id,fahrzeug_id);
